BEGIN;

SET LOCAL search_path = public;

ALTER TABLE public.professor_review ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.professor_review_course ENABLE ROW LEVEL SECURITY;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (278::BIGINT, 'Deja tareas largas, pero sirve para ir practicando, explica bien y deja todo muy claro pero puede ser un poco aburrido. Los rubros para evaluar y las instrucciones son súper claras. No califica duro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '0bb142974a6ea8f582c4d1dac979bf80f7a49fa06f21d96b0f0c0803637d96a7'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'No lo recomiendo, si no sabe de programacion, explica bien, el problema es que explica ejercicios muy sencillos en ppt y a la hora de examenes que es el 100% de la nota son mucho mas dificiles, ademas le gusta humillar a los estudiantes y la agarra contra uno el resto del semestre, nunca más.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2026-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'fef7289534ce520ecaa3b30e07114b5984ac637693b9bc61ce8c2be9b82a0735'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Excelente profesor. Valora mucho la participación y que el estudiante esté repasando y practicando. Aclara cualquier duda. Eso sí, si usted no pone atención en clase o no se esfuerza se pone amargo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-21T00:00:00+00:00'::TIMESTAMPTZ, '59558237ca6ceadf2dc876ce570c0e7c6ea00734274d7b192e311892f35f2d44'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'No es mal profe pero si ud no sabe programar no se lo recomiendo. Hace puros quizes en papel, deja tarea casi todas las semanas y le pone el ojo si ud no presta mucha atención, hace varias preguntas en clase.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, '1fe9d56c5df212f8176b3e067be3a8cea7d7e85597ed73022fcd6dfeee030d1f'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es claro para explicar y repite bastante. Usa diapositivas que pasa a TecDigital. Si ud no entiende le puede preguntar. Depende de lo que le pregunte será el tono. Deja proyectos y tareas muy largas, pero se aprende bastante. Los exámenes son dificiles pero no es duro para calificar si ve esfuerzo.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2025-08-21T00:00:00+00:00'::TIMESTAMPTZ, '2eb6d3229f3bfa271102687faa47483bcb691a8deb4f42348e4c597b7a6be7d5'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'en si el profesor es muy bueno, solo que si deja mucha tarea prácticamente como una tarea por semana de 20 ejercicios cada una, si usted sabe programar súper recomendado solo que es muy grosero si usted le pregunta algo y después de eso TODAS las clases le hace preguntas y ya no lo suelta'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'e904576eba32e0bb248c1631b3761b261e21ffa2fca21f4493bc3cbcf4fe9f15'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es un muy buen profe, se ve que le interesa que el estudiante entienda todo de buena forma y esta dispuesto a responder cualquier pregunta que usted le haga. Si es necesario prestar atención en clase ya que hace preguntas. Hace muchos quices que son muy similares a las tareas, y no hace parciales'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '318117643c2f999c83f3fe14c9a4c07b1e574702846e9f18a4a8d8fa0c06e4fd'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'La manera en la que habla hace fácil distraerse o aburrirse pero si saben algo de programación o pueden ser autodidactas se los recomiendo. Él brinda material claro y es claro con lo que califica, solo que quizá hace mucha tarea pero uno aprende practicando tanto.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2025-07-10T00:00:00+00:00'::TIMESTAMPTZ, '434d1177753b656e1185dd48c8000f6e01fa8b5969ece7e55fdf33d2306afe4b'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Considero que es un muy buen profesor para quien nunca antes ha programado, como fue mi caso. Las clases son muy largas, las tareas son gigantes y son muchas tareas, Intro es 100% exámenes, es estricto al calificar. Y es grosero si uno le hace preguntas'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f4155bd27c9f922f0ba05b90b1020ee8da5d7c4993bca1e276b996549a403550'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Sus clases son muy largas. Deja tareas bastante largas. Los quices son fáciles pero son de 2 ejercicios y por lo general una pequeña parte del código es 50% de la nota del quiz. Si lo ve distraído probablemente lo regañe bastante y no lo suelte durante el resto de la clase.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8c60dc57a406f8baf41f9d45072ff8854ccda69cbfd0e1524636f82eae099c23'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es un buen profesor para alguien que no conoce nada de programación, pero sus clases a veces si se pueden hacer largas, hace el curso casi que 90% presencial, practicamente se tiene un 15% asegurado de los laboratorios.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '133e68c1636105f1d5cfb47eaa4566a5992be39bf1a1136e03bdca5118ee949a'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es bueno explicando, las diapositivas hacen que quede muy claro a parte de que repite mucho cada punto. Al hacerle preguntas a la hora de la práctica suele ser chocante en su forma de responder pero fuera de eso se siente fácil el curso'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-09-30T00:00:00+00:00'::TIMESTAMPTZ, 'e4837447c652091c547e3c140d9c72266fc2ce96c0fd8e5b821d7ff18c224da0'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es buen profe, aveces explica de forma extraña, pero las presentaciones son bastante claras, aunque suele ser un poco desorganizado con la entrega de proyectos, no califica duro y suele atender dudas. Como persona puede llegar a ser un poco molesto; aveces puede llegar a responder de forma grosera.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9a2dca76059fd2366a1cc0f826080ea2f9bb1b1004d82cdcca1fd143510f093f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es muy amable y cómico (lo intenta). Todas las veces que tenía dudas por correo me las respondió y bien. Las clases pueden ser lentas y aburridas, y repite mucho el mismo punto. Como él dice, empiece los trabajos apenas los mande, están hechos para que se tome (casi) todo el plazo en hacerlos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '5932bd2a6b3c31f467fac29301820abd5491f68947279a3fcedf0f9ca0700ad8'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Mejor profe para Intro y Taller, las tareas son largas y algo duras, pero créame que usted sale pulido, puede hacerle cualquier pregunta por mientras que no sea de hace dos semanas. Ponga atención porque no le gustan los estudiantes desinteresados y se nota. El profe se ciñe con ud si le pone.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Inspirador']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '22a0e02c7c04c3cbf8ee4795e109e0219991523a2f69884ec3a0c82b8b94d717'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Al principo las clases son un martirio, si van a matricular taller, preparense para que se ponga a leer diapositivas y a que haga preguntas super equis, ya después la clase agarra ritmo hasta que llegan los proyectos bien fokin largos y dificiles, y también preparense para las tareas largas que deja'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-06-07T00:00:00+00:00'::TIMESTAMPTZ, '85a3c05be3631e6fe2630e556d2926cddf6eb8c8322ecac3728799531cafe049'::TEXT, ARRAY[1022]::BIGINT[]),
    (278::BIGINT, 'Muy buen profe, se le entiende y se le siente el interés que tiene por los temas de los que habla, pero prepárese para prestar atención siempre y estudiar en puta, sino se lo lleva el diablo, cursos de solo exámenes, y trabajos larguisimos, tenes que entender la materia bien y los examenes complicad'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, '1e8e4f81e8a5976c9a14421e0390ebe96cb76f79b16b661c4b1f58d041360488'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'De los mejores profesores que se encontrarán en la escuela de computación. Desde el inicio explica las bases para programar y va añadiendo temas conforme uno aprende, lleva el curso a ritmo perfecto. Los que les va mal literal es porque son vagos con tareas y estudio, este profe es la mejor opción.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-05-23T00:00:00+00:00'::TIMESTAMPTZ, '98f3a8e3e6a2b69c23a092017499e8e053472a5ae9851e1c4fa918826f1cac78'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Si a alguien le cuesta la agarra contra ellos el resto del semestre y los humilla en clase. Los proyectos son excesivamente largos y las tareas también y os exámenes son más difíciles que la práctica. Hágase un favor y no se meta con él en primer semestre, personalmente me hizo dejar la carrera jaja'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2024-04-21T00:00:00+00:00'::TIMESTAMPTZ, '0ab77b8529fc277627b32bbc33cafa50421568547df2f2c49a5e753f98dbcb3c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es un buen profesor, da buenas bases y explica muy bien, deja tareas semicomplicadas pero si se es autodidacta se hacen fácil, los examenes no son complicados si uno hace las practicas, en fin una buena opción.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, '36708f8b5869962f7da0a22481bc7633b223565f7815bf6f03a20bc343e9537c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'El profesor es buena nota pero asume que todos saben programar, si es su primera vez en eso mejor no lo lleve con él. Las tarea son excesivamente largas y los proyectos son demasiado complicados con temas que no se vieron nunca en clase, escudándose en "tienen que investigar".'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'c61f08fa8916fb9c0fda9ca84a7a48dc72867ce75158623f940d54f12ec4bf0c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es muy buen profe, yo entré sin saber absolutamente nada de programación y me gané una súper nota, los que dicen que no lo lleven si no saben programar son unos vagazos. Hay que ponerle, claro, pero se aprende un montón, y los exámenes son durísimos.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2023-09-29T00:00:00+00:00'::TIMESTAMPTZ, '6008be0e3d1f8964e337f3da7a6028a9346e545fb7522c76486359239c3b1eeb'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'El profe es amable e intenta que todos entiendan pero debes prestar atención, sino se enoja y se lo caga a uno. Las primeras tareas son bastantes largas pero ya luego se relaja, los exámenes se hace a base de eso y los proyectos se toma demasiado tiempo, y hay que investigar mucho uno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-08-21T00:00:00+00:00'::TIMESTAMPTZ, '5283a1cd7dfd87330bbbcb122669eb9e1982d08bf58214a2566979b12915fae2'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Piensa que el 1 es primo'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2023-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'a356cd8b61255b1990738e342d7143864f791dab79ac3dadc3e7d9a5d5f31191'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'A conciencia no le metí suficientes ganas a el curso pero como le metería suficiente ganas si el profe no hace que uno se enamore de la materia ni que le parezca llamativa ni que uno quiera aprender más, además su edad tampoco ayuda ya que es de mente muy tradicional, si puede meter con otro hágalo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '20'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3a04f4959a3c0553b3c0a20ef644cf8fb7cf2da8c25633c164c6823c9bc64885'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Desde mi punto de vista, es un excelente profesor, en general me gustó como explicaba, el iba lento para las personas que no sabían nada de programación (yo). Sus exámenes fueron normal casi a complicado, pero mientras que haga las tareas, ponga atención, vaya a clase, participe y sea respetuoso.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b73df258cefe24a85288d006d60082fc87e7e7322f9e15f4affd9a497d323d38'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'NO MATRICULE CON EL SI NO SABE PROGRAMAR. El curso es sumamente dificil para alguien con poca o cero experiencia en programacion, si ya tiene conocimiento previo y es confidente en este entonces es una muy buena opcion'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Inspirador']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e8ea35f996851c41755a9c45432b4108c7ec0754f530c753a0f37ab26b14072e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'el profe es buena nota, pero si usted no sabe mucho de programación, busque otra alternativa, los trabajos, proyectos y exámenes son bien rudos, así que si matricula con el póngale bonito.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '3720e684657417f221c2d52c51ddd2e0f7412509fce498860a7853c4ced38f7c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Deja trabajos y examenes largos y dificiles que requieren mucho esfuerzo para ser un curso de primer semestre. Eso si, el profe explica muy bien y si uno le pone se aprende un monton. Para los proyectos brinda rubrica :)'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7224ad1964b4987b041a7f5387bf4c012e16d41ab6a57d669d639e4892dca1b2'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'No y simplemente no, no matricule con este señor, oh bueno, si ya sabe mucho de programación pues sí, de lo contrario, busque otra cosa'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2023-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'd67d4e079c67f0482e80806816a31ba91160884879fed64c8114068145734844'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'No matricule con el, este profe a menos que ya sepa de programación, pero si es nuevo, no lo haga, sus exámenes y sus proyectos son para personas que ya hayan llevado el curso, además de que se enoja muy fácil, y se enoja mucho, hasta el punto de gritar al estudiante frente la clase, no matriculé'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-06-03T00:00:00+00:00'::TIMESTAMPTZ, '49756a1e86c72bf55f41b0d1dda45599328b120b39b48928ffc421eb063bf74a'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '50'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-06-03T00:00:00+00:00'::TIMESTAMPTZ, '384b59a1012956f92a9cc89e5c7816d25d63ae96f8d4219bd73d21be4fe7b4dd'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'No lo piense más, metalo con él. Recomendaciones: sea respetuoso, interesese en el curso, trabaje las tareas a conciencia. Con solo eso, de fijo le va muy bien'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-01-17T00:00:00+00:00'::TIMESTAMPTZ, '8c523cb5b1a91eb0c773b911f566fe898a64af517c3c8faebf0186b800b69e90'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Lo recomiendo para quienes no saben nada de programación porque da bastante lento las clases y explica paso por paso. Hay que poner mucha atención porque hace preguntas en clase. Califica regular.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2022-12-29T00:00:00+00:00'::TIMESTAMPTZ, 'f0c3c48302054d31b8fffd4212abeb27d7bc5c72aaabbacab85a5da537d01784'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es muy accesible pero se debe de mostrar interés en el curso, las explicaciones son claras y no deja tantas tareas. A veces puede perder la paciencia'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-12T00:00:00+00:00'::TIMESTAMPTZ, '6ef2d52dcf8da845a1446f7d5e8a8b542708e5bea79dc3e244daaba0490d88f9'::TEXT, ARRAY[1030]::BIGINT[]),
    (278::BIGINT, 'Hace el curso relativamente teórico, pero muy relajado, por lo que para un semestre II créame que lo va agradecer. Si cumple con los trabajos de buena gana fácilmente obtiene un 100. Pero interese en la clase o el profe lo regañará de forma dura.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'bab007b4d6eb48061c227bfce1173a267e54200ef6c296387f7b9669a967d496'::TEXT, ARRAY[1030]::BIGINT[]),
    (278::BIGINT, 'Es buena nota, explica muy bien y los exámenes son de dificultad normal, a veces da más tiempo para los que aún no lo terminan. Lo recomiendo, especialmente para las personas que no han llevado nada de progra, el va muy poco a poco.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-12T00:00:00+00:00'::TIMESTAMPTZ, '1e189bab133608383518b23b96661728366dfdf0fdde1aced9e33c3313d1b425'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-09-15T00:00:00+00:00'::TIMESTAMPTZ, '3fa5a0b9f5a6c88b3679eb8b76a497d9f3b17c42d2ee4088406cc4fae75a5fd6'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Explica claro, pero las clases son largas. Empieza tarde, y a veces se pasa bastante del límite. No deja mucha tarea, y los exámenes son un poco más duros. Aprecia la participación en clase. Se aprende bastante. Para dudas de ejercicios, busque en google y youtube en inglés.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '30930a3b512f59acba70e93a6ca4bd5dad9f9314428e37908a4c2699e5b0c5ea'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Deja muy buenas bases. También deja muchas tareas, lo usual son unos 12 ejercicios con cierto grado de complejidad, pero son grupales (2-3 personas y también deja pedir ayuda a otros subgrupos), además de que él mismo resuelve unos 4 ejercicios de la tarea, entonces no es nada pesado. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '4c064ad1498d9dcba204ee25611a780db41c0cb5bffa8022eed8c7abf24db78a'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Si ya sabe algo de programación matricule con el, se le va a hacer muy facil, lo van a poner a picar código como loco lo cual es muy bueno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'b9211049509c2033f42f2b900957f68f4782e5f453f09d4ba05593cd710573a7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Se deja con excelentes bases y los trabajos, aunque son largos, fomentan la utilización de lo visto en clase para solucionar problemas. Permite hacer tareas en grupos. La clase se puede tornar un poco tediosa y puede empezar y terminar tarde. Puede ayudar cuando se le pide. Aprecia participacion.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2022-05-27T00:00:00+00:00'::TIMESTAMPTZ, '42ac0f381ade3637b9695071c008be488c8bf67f3cd9841774a68813efe315a8'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'El profe es muy pura vida sin embargo se enoja fácilmente. Las tareas y exámenes que dejan no tienen que ver con lo que se vió en clases.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2022-05-08T00:00:00+00:00'::TIMESTAMPTZ, '169043e4e40195851ac4f1b1062d720d1ab512f46f05cd93d195e49e3c13427f'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Las tareas que deja son muy largas y muy complicadas. En muchas ocasiones, lo que se ve en la clase no brinda las bases suficientes para realizar los trabajos que deja. Se enoja con falicilidad.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-05-08T00:00:00+00:00'::TIMESTAMPTZ, '64a3a15849dfc6b6034babd99cdfac706a21c61abbd0bbdc93b0c9e96bd5ed5b'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'El profe es bueno y muy tuanis, pero no le lleve la contraria y haga lo que le pide porque se enoja facil.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2022-01-04T00:00:00+00:00'::TIMESTAMPTZ, '3736b88ffcf867287861201b8b78282036835eb915a664bc5aa88fd95837dcc9'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Las pruebas no tienen mucho que ver con la materia, califica temas que no se han visto muy bien o no se vieron Parece que no le gusta que le pregunten porque le custiona al estudiante si ha estudiado, es medio grosero Es dificil llevar un curso asi con un profesor así'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-10-08T00:00:00+00:00'::TIMESTAMPTZ, '104fb7dd057303c7eee10e2909982d3265ed3b942ca8a8bd445fb0abff773fa7'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'El profe es muy bueno. Explica de manera excelente. Le interesa mucho los estudiantes y adecua dudas. El problema es que sus exámenes son muy DIFÍCILES. Algunos exámenes no tienen que ver NADA con la materia, no lo recomiendo por esa parte.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2021-07-25T00:00:00+00:00'::TIMESTAMPTZ, '1435bc33bbdc29cb1d6548e6f498c6da0fd7a21d0c1c4f9b58373199994d495f'::TEXT, ARRAY[1020]::BIGINT[]),
    (278::BIGINT, 'Para empezar en progra es el profe más suave que hay. Se aprende un montón con él y es flexible en las entregas de proyectos y en horas de consulta. Estudie el material para que no se amargue en clase inicie los proyectos desde que se los dejan para que vaya tranquilo. Haga las tareas a conciencia.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, '16c3b3088dce13c452ee2546a3de53ecbf4d86a95c02225b4d6682d769a991cd'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es un excelente profesor!! Explica muy bien, y repite las cosas muchas veces (lo cual puede ser aburrido, pero también bueno si se distrajo o no entendió). Siempre da tiempo para entregar los trabajos, eso sí que los trabajos suelen ser bastante largos!! Si quiere aprender matricule con él!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '9824ebcbc91d7ac131c8d32778eb8d6b88818b5db0f4cf991c4b45fd67d3d7a0'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Los exámenes pueden ser difíciles si estás empezando de cero, regala algunos puntos con ejercicios extras, trabajs largos en la parte de los proyectos de progra, el profe es pura vida, explica bien y seguramente los ayude dudas o alguna otra cosa relacionada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b39f5b66ad88cc5feaa7f61aa1b4390a0e0ce6a2bdbb39d00ff01b8bb19ba053'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'no lo lleve con el, explica con ppt y asume que usted sabe, no pregunte porque lo va a agarrar de burla o mas bien lo humilla. CORRA DE AHI !'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '580122ec968c1f10ddc2b4d9601338c38b07da17415217b122e57853d559a963'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Explica todo con presentaciones, para las tareas y proyectos hay que investigar bastantes cosas que no se vieron en clase. Da tiempo extra si se pide.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'd4d59ac5c71d1e4dce975385fec43a99670b67a2deec9a9120086e425653f2bd'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'Es un buen profe pero si usted no se lleva con las presentaciones de power point mejor no matricule con él, el profe siempre esta abierto a preguntas y a repetir las explicaciones. Deja tareas varias tareas largas asi que organice su tiempo lo mejor posible.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '4bb0234b9e4279b03c6d2951194987e297a9a0d0fe9d2cdb570873874eafd054'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'No llevaría con él si fuera mi primera vez en el curso, usa presentaciones de PowerPoint muy largas y monótonas, no se puede preguntar ya que lo toma a uno con sentido burlista, se sale del plan establecido y pide proyectos donde hay que aprender materia que normalmente no se debería dar en el curso'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '3f4a478e1b677de7c9e84aec0725e51c1208c817172d72aed1cb023908812b80'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'Enseña a programar con presentaciones de powerpoint, asi que si usted no sabe ni un poco no meta con el, ya que le puede ir mal, el pretende que todos sepan algo y pregunta mas si ve que usted no sabe, es un poco humillador.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '54b975f2c39485794419da8127739576de3f654c088f990fd2e6518d126b5b4b'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Puede ser algo grosero si no le contesta o si le hace preguntas de cosas que él ya había explicado, pero realmente es muy bueno, deja quices, tareas y prácticas que ayudan para el examen, se pasa fácil si hace todo. Las clases pueden ser algo aburridas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '7082a3fba8b302b2526566dd47f14f3d7ce13b781ca2559da4f53eb1e8c95ea6'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es genial para aprender, explica extremadamente bien. Las tareas y proyectos son larguísimos pero si se hacen son 100 en examen en los cuales solo evalúa lo que el enseña y no inventa nada como otros profesores. Tiene un carácter fuerte para los que no ponen atención (Pregunta en especifico).'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ed57ec754d41ce5379a71b17e8bb77a2d7b5971373df9691671f3f435f71e3db'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'Es concho y si usted no le contesta como el espera puede llegar a humillarlo frente a toda la clase. No explica mal y sí deja tareas que sirven para hacer los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '81fac4f00990015ae7d59c8070b6b4d6cec7aaada388809d52b147fbc4715e09'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'El profe no es mala persona, pero vuelve el curso muy pesado, si usted quiere aprender de verdad lleve el curso con él, pero si solo quiere pasarlo, busque a otro profe.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'fc661f0652c7a5becf5542a6bc3852bedf8e52ddcb1aa5be3fa43e8d5188ca85'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Los trabajos son rudos y largos, hay que hacerlos con tiempo. Algunos se pueden hacer en pareja pero si no conoce a nadie mejor hágalo solo. Los 4 exámenes son fáciles si uno va haciendo las tareas. Si necesita ayuda de fijo en internet va a encontrar algún tutorial. Se aprende bastante'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '35633199e6fb79068dbca0ddbd6c546954de9e3003fbb04a1743477593ee9e17'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'No da las notas, puede llegar a humillar o ser un poco concho pero en lo que respecta a la materia es excelente, explica super claro y facil . Las tareas hagalas con tiempo y siempre hace ejercicios parecidos en el examen. El asistente es super buena nota y ayuda montones.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '55625d6ace1f2a7721ad2d8c33a32f9d1bb5b97da1c0d039339e3ed6da036848'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'william es un amor! tiene mucha paciencia, da más tiempo para los proyectos, hace actividades interactivas con los estudiantes. tareas son largas pero se aprende con ellas y son casi iguales a los exámenes. la vocación de enseñanza la tiene muy bien cosa que el resto de los profes no'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-01-11T00:00:00+00:00'::TIMESTAMPTZ, '08713b13d1521105d5f5bf54797bb40aa998f031c5e2c9fc620ad12ef689bfdc'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'No es tan malo, pero tampoco se puede decir que es un profe super bueno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'fff7b71a5bc24fe09349b346915bfa91b560b131bc420a921df66183ba26974c'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'En realidad uno aprende con el hombre por los bretes que deja, se aprender a hacer muchas cosas con información muy básica, eso si los exámenes son duros pero si hace las tareas se saca bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '88ce95cdec6da0a9931939c7c4cb5cebadc70b0ebcbc72797495031fbbf41207'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Explica despacio para que todos puedan entender, suele ser repetitivo pero eso ayuda a que se le pegue lo que se ve en clases. Es muy flexible con la forma de programar de los estudiantes. Los exámenes y las tareas son muy sencillas. Los proyectos si son largos y complejos y hay que darles prioridad'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'b42be0589f76a612bf6365d74651eee96a86a37d2f13f0d0ba17329b082c97aa'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Muchas veces solo lee las diapositivas y no responde muy bien las dudas. Deja trabajos muy largos. Es un profesor consciente con la carga de otros cursos y a veces ayuda al grupo para no cargar mucho la semana, mas que todo con fechas de entrega.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '06ee3d7a110e5238aa727c7cfc68294c770c18b948dc2184dfc9fb003b504a21'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Un profesor muy bueno, explica muy bien pero deja tareas muy largas, si su objetivo es aprender a programar python matricule con él, si su objetivo es pasar fácil mejor busque a otro profe'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'dc7e6dee00eb93747e92d4c0061f9d02c351f10dcd3888d33f8e60fe7a6be858'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Deja las cosas claras y se aprende bastante si uno quiere pero la manera de ser del profesor le quita las ganas a uno de aprender. Es fácil pasar si se lleva la materia y las tareas al día.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'e771436ded74767a994082da73b2d3bebaed3714e73a6e19d255279f09693974'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Como persona es súper bueno. Como profe tiene sus cosillas. A veces la explicación no queda tan clara. Cuando le preguntan sí responde pero a veces no capta bien lo que pregunta el estudiante. Y sí deja mucha tarea. Aunque sí ayuda mucho a final de semestre.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'b9ea36e9b42992f3c4a49645420d9e37a94f241c854a8ab2bc30f7292dde0558'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Pésimo. No da ejemplos, solo deja unos pdf con la materia básica y después de ahí uno tiene que jugársela solo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'f74b9585c75431c2d44d638c56236044806ad9ce9d501c4f229d1d1cc6ea98cd'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'El profe enseña lo básico, usted aprende por la gran cantidad de tarea y programas, pero si no le interesa aprender a programar no es su mejor elección de profe'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '6f7282a0951cd31fe8abdc9ef4d1bfea0ff93011b080612bf9700da78d280dc5'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'El profe deja tareas a lo loco, a veces son de resolver 40 problemas (no exagero) y usted jueguesela, sin embarlo, cuando usted llega a hacer el proyecto o el examen se le hace fácil por el montón que ha practicado con las tareas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2020-05-20T00:00:00+00:00'::TIMESTAMPTZ, '6783eff51f5427af11053a28437873c4c8ec895ec41268cca55817eb3d537b64'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (278::BIGINT, 'El profe es bueno. Pero hay que dedicarle bastante a las tareas y proyectos de taller. El explica muy bien y desde cero. Además es bastante flexible con las entregas de los trabajos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-28T00:00:00+00:00'::TIMESTAMPTZ, 'c8d7a7b2ffb9792594a2f920267547d3df5d4ec2ecb93c9118993e3ff04d8d21'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es muy amable, y como persona es excelente, pero no es de enseñar mañas ni de dar ejemplos, solo da la teoría (da pdfs muy buenos, pero solo para aprender las bases) pero deja trabajos enormes de una semana a otra en los que uno tiene que estar pegado por horas para resolverlos si no se sabe cómo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-02-19T00:00:00+00:00'::TIMESTAMPTZ, '2471f1f2f399fcf7e1f66ac35dba9dac8087895f8b0a06cddb07035124239956'::TEXT, ARRAY[1249, 1035, 1253]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'c578c62f7bdd2a2a3b9a747cedf222bbee1f8b0baf38fa83b5cf0fc10c52bad8'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'antes me había quedado con otro profe pero con william lo pasé perfectamente, es un amor,es cómico,da tiempo extra para los proyectos y tareas(deja muchas)pero son práctica para los exámenes, en los exámenes deja escuchar música, deja corregirlos y deja hacer un ejercicio en la casa en los finales'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-26T00:00:00+00:00'::TIMESTAMPTZ, '42ac29fd09db84159fc88a7d907a0ac7cb047094b4593b10a2ace769a2eace2e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Uno de los peores profes que he tenido. Muy malo explicando, llega a leer diapositivas. No lo recomiendo para nada.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, '449b2cf365766a890ee0540f69121e2b51884fc4b787f3befb3ccc0e301e0c44'::TEXT, ARRAY[1035, 1253]::BIGINT[]),
    (278::BIGINT, 'Es un profe terrible, no se le entiende nada, hace ver todo muy fácil y a la hora del exámen pone ejercicios dificiles, sus tareas son complicadas más que todo porque apenas explica como el 50% de la materia, no matricular con el si es primer ingreso o no sabe programar'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2019-09-20T00:00:00+00:00'::TIMESTAMPTZ, '7d0bba880e9837c88aa51cd3d7330cb6d0b87f2f291ea4ee6a40ea6f254fcb17'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Las clases son con diapositivas que solo lee. Los examenes, tareas y proyectos son bastante largos y califica duro. Uno tiene que investigar mucho por aparte y si uno le pregunta algo es muy probable que le diga que debería saberlo ya.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '211430a4a7f5438ec6efcdcd1840125bd63586f245cb428e7f896f5f4bc7eb38'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'Va a la clase solo a leer diapositivas, no resuelve ejemplos, pone uno facil en la presentación que lee nada mas. Si tiene alguna duda no le va a responder porque es algo que “ya deberia saber”'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '2de76700d7374b7201fd1fa9b24674cd1d2f820b73825ab9b9ca163114e78f3f'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'El profe es muy claro con la materia, pero no es bueno a la hora de ayudarlo con errores en el código. Lo impulsa mucho a investigar y los proyectos son entretenidos'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '77a5754c92f014d0d7170b76a8b5e2d4a04fd5df019454ad645898fd01142131'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'William es un caso complicado jajaja, si es cierto que los proyectos y tareas son demasiado largas, pero es demasiado flexible con la fecha de entrega, es demasiado comprensivo, solo que a veces se enoja cuando la gente no presta atención, si es bueno tener buenas bases de progra.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '45'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'fed14dd3845a6063c62a4b68db5f72ffa24557648769ce32f94d6b6969f53370'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es cierto que las tareas son un poco largas pero tampoco es como las describen en otros comentarios, gracias a esto uno está bien preparado para el examen, explica muy bien y es flexible a la hora de poner las fechas para los trabajos además es muy buena persona lo recomiendo al 100%'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-07T00:00:00+00:00'::TIMESTAMPTZ, '75239ea440659b8a7d21ea36dd3c13d179d94b4baf4d769ed18cde785898f9c4'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2019-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'a0fa81362d5f72f74ad813e3296f7e405d29b559ee4f4f71907344587ea91a0c'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Muy duro, y se enoja cuando le preguntan cosas que "deberían saber" pero buena gente y da puntos extra en los exámenes que a veces terminan siendo la salvada del curso.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-26T00:00:00+00:00'::TIMESTAMPTZ, '487c9df24cd5099238ade618e7898f3d789cf1981f23f57343c8f69cb16d23fc'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'Señor necio, tiende a humillar a los estudiantes. Pide que le pregunten cosas y cuando alguien lo hace, el lo regaña demasiado y no se le entiende nada. En resumen cuesta mucho que el aclare bien las dudas. Sus clases son tan largas, confusas y aburridas como sus tareas. NO recomiendo matricular.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-05-20T00:00:00+00:00'::TIMESTAMPTZ, '079f87e0aa7cd48def305cd48760b13c51c47a6735e6b8b674dad0da55c50bcf'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Evaluaciones muy largas, si va a llevar con él, preparese para hacer proyectos enormes'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'e8d3695e5e34bf4ea42dd7b634db3f8d1f40e4e6ba65c0f464dcaf925f29d2d2'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'No hace proyectos. Su actitud es difícil, no ayuda a los estudiantes y tiende a tratarlos mal.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-27T00:00:00+00:00'::TIMESTAMPTZ, '288dd9a4df18df6a13c298c17dd28ff079d40944403eab5f874fa16dac644c57'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'El asunto con él es un poco complejo jaja, si se aplica con la materia le beneficia porque te llevás bien con él. Tiene que ser preciso con sus dudas porque no suele responder lo que usted pregunta. Evalúa justamente y las evaluaciones son un poco extensas. Los exámenes son normales. Hace curva.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'ad0f933f4d0bc44d05d626013912213dda642fe487daddcc168e7ae7e52ab910'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'Hace preguntas a personas al azar y lo humilla si no sabe la respuesta. Quita demasiado tiempo por las tareas largas y da la clase como si todos estudiaran computación, si no sabe programar NO matricule con él'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd468f102cbeab99325c26ac53ead6177bf11ee9ec8059c747a4aa34083a394d7'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es buen profesor en cuanto a la explicación, pero califica demasiado duro, y si uno tiene duda el mae piensa que le está leyendo la mente uno y le contesta otra cosa, tiene que explicarse bien para entienda su pregunta. Tiene muchas preferencias, pero si no lo es, lo trata con cierta indiferencia.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'bdda114d920f255cecc4c689ddbccf1681a1891b23d1331b5eafede44563c5c3'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'Pésimo profesor, califica demasiado duro, las tareas son demasiado pesadas y ni hablar de los proyectos. Trata de humillar siempre a los estudiantes por no saber algo. No volvería a llevar un curso con él'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '45'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, '354a441a01e1ba0395b16bf8cd854354f9567fea2bb8d816b573022061aa4819'::TEXT, ARRAY[1253]::BIGINT[]),
    (278::BIGINT, 'Excelente profesor, deja tareas largas pero con el tiempo usted va viendo que las mismas tareas son cómo estudiar para el examen y por ende es una ayuda tremenda, proyectos entretenidos pero pesados (hice un "kenken"), si ud tiene dudas el no deja de explicarle hasta que usted entienda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, '14e7e75fd6246600b35ecd90386dd1394c4c072df0cf9de9be5674be1bd040d9'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (278::BIGINT, 'si no sabe programar no lo lleve con el, además si lleva muchos créditos el no es una buena opción ya que toma mucho tiempo. No llevaría otro curso con el.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-06-30T00:00:00+00:00'::TIMESTAMPTZ, '041ee1c40d98b61d8875eaa82f10a3e9b5ccbe523dcf108b2f3fe75d34c7a89c'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'NO RECOMENDADO PARA PRIMER INGRESO...'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'b1dbec485920a69e98f79cfb51fca288f2a7e04e2565c67fb20e23efa9b7ccab'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Tareas largas y retadoras, exámenes difíciles y progras individuales y mucho material de apoyo, de los mejores y más duros profes para esta materia, SUPER RECOMENDADO.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b651e9ee8a2fd67488b8d413abea2b527b7207ed7d727df6ba1b9a9368a328ec'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es un poco difícil, es estricto y hace exámenes rudos. Pero explica bien y da bastante material de apoyo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '20'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'cd777e93dc45605de37d2f7f4fabd6b523262b796d1812f080f49fdeed82067f'::TEXT, ARRAY[1020]::BIGINT[]),
    (278::BIGINT, 'Súper recomendado. Explica súper bien, los labs son fáciles y los exámenes aún más. El mejor profe para elementos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'f24c7ddc90a22666d84eb8e6864fb1e901b9d0f168b2c3f21b086e439f4f3704'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Explica desde 0 todo. Deja tareas largas pero se pasa. Y son similares al examen.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'f17491302463adb7f0ca768e78c878fc32240ccc12e9a247a950b8e2db0ee324'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'No recomendado para quien no sepa programar no se envarque'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-04-03T00:00:00+00:00'::TIMESTAMPTZ, '41662d528d0fad9237ece0cfe229df080bdbdba2940dd3d33579dc0e56891edc'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Muy buen profesor, pero tiene que ponerle para pasar los exámenes son largos y un poco confusos.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '8fd80fe45194d4f4e8b50258c3296b737ddb28bbb2ba8d6d60d823fb1495c28a'::TEXT, ARRAY[1038]::BIGINT[]),
    (278::BIGINT, 'El profe es bastante comprensivo, explica muy bien, hace bastante practica y se interesa por el aprendizaje de los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '325002dd1570538f69520f16ca9384bf7757f4f35c94b99612138a6af481e675'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Deja muchas tareas largas, progras individuales, se aprende mucho con el, mas de lo que se da usualmente en intro y taller. Las progras son largas y hay que trabajarlas, si le pones seguramente pasas.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6a407d41ddb92cc6943bfdd6425ca4cc2c4cafc7ddb6a87fece2b6ed7948eed0'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Buen profe, progras duras y examnes duros'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '5a02366cc9a5cfea05f0aad72675007a8d91309a62e08e6919fab1e3659aadf5'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (278::BIGINT, 'Explica bien, mucho material audiovisual.Sin embargo sus exámenes son demasiado difíciles para un curso de intro y son a mano, califica muy duro. En las progras no ofrece mayor ayuda y son individuales. No recomendado para este curso si no tiene experiencia programando.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1d8d6bb4fbe8186c1d0bab027c4a29a70d73adf1fb166387883658681ce4a3f7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Califica muy duro, deja tareas muy largas y no valen casi nada.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '45'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'bdef7a67d919a86f3fee35ea17cbe2a8776bef8c78501105ed43fdd8ed0a6ee9'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Excelente Profe... Deja bastantes trabajos que valen poco porcentaje, pero eso lo deja a uno listo para los que sí valen bastante, súper recomendado.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '735b0745d4a0d86cd99acb83b64ef8784fe43c6cba873f7f2692ba4bdaa5114f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Le fascina humillar a aquellos que tienen poco conocimiento, clases de muy poco provecho, evaluaciones muy difíciles, hay que ingresar al grupito de la argolla para poder pasar.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '26536a14fd09c3f957826c1212263b91ba42398915f6097a077d22ce91da85d7'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Uno de los peores profesores en la historia. Quita puntos a personas que se los merecen y falta el respeto en clase. Clases SUPER aburridas y no explica, lo único que hace es leer las diapositivas. Pregunta a todos, si no sabes te trata mal. No metan con esta persona.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2017-06-03T00:00:00+00:00'::TIMESTAMPTZ, '45b68f29f371826eca6759314f7f66de56024d9646c7c5536b6eeab1c26b9e74'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Las progras son individuales y desde la primera es con interfaz gráfica, los exámenes son un poco difíciles. Llega a la clase a leer la presentación.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-05-29T00:00:00+00:00'::TIMESTAMPTZ, '050a3d85049409552f6d849f73390b7a0e637e4fd2ad26b7d19d3fe281b01832'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'tareas de taller larguísimas que valen super poco, las clases son aburridisimas, solo llega y lee una presentación que luego sube al tecdigital, exámenes en papel, si quiere aprender a programar y hacer cosas interesantes meta con otro profe'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'b178053606cd69500c0e1e24ced18d085e07d82c04b1d35dbaf5cd9322a10d64'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Bueno para llevar por primera vez, explica bien y los examenes de intro son algo complicados pero no imposibles, hay que pensar. Sus progras son individuales'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '3cf724e23ca0d2627c2676fa92731aa17d248cdd9651b4a03baeb81197b0e343'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Él tiene presentaciones preparadas para las clases y con eso explica muy bien. Los ejercicios de él son medio rudos, pero eso lo deja a uno muy bien entrenado, no le gusta que uno se adelante con la materia o use otras cosas de programación así que cuídese de hacerlo exactamente como lo pide'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '1a884893c24e72b3da18ea546d5d8e3f2719fba990ece5263344542beba17917'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '45'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6c2ee92562e8bc32954763b431bb3308d50cb94c2fbaa64627169536c70e584a'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Excelente profe, uno realmente aprende pero hay que ponerle bastante para pasar'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '36086528f6e90c68ba3965dff9ae6a54b9b183f4c44251e488f26745d8e16d82'::TEXT, ARRAY[1043, 1037]::BIGINT[]),
    (278::BIGINT, 'Explica leyendo las presentaciones y da ejemplos Se enoja si uno le pregunta algo que ya explico en clase, pero al final termina explicándolo. Los exámenes son muy largos, siempre son parecidos a las prácticas que deja, pero no a la primera sino a la segunda que sube como un día antes del examen'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '78238a4544fbe3872e99d478bc92c7d95ad294cc45216789eda0a37c2fbde529'::TEXT, ARRAY[1038]::BIGINT[]),
    (278::BIGINT, 'Es buen profe, aunque hay ocasiones en que sus evaluaciones y calificaciones son proporcionales a su estado de animo. Hay que prestar mucha atencion porque hace preguntas durante la clase y se molesta si se contestan mal. Aún así, explica bien, atiende dudas y los cursos no se vuelven tan pesados.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0d4a5198dc85d89a5b17d2bac3a7d18de55fae5348bac03710bbd92e8c0ecc06'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es una excelente profe, deja proyectos largos y en el momento uno siente que lo que pide no tiene sentido, pero al final del curso un aprende un monton sobre los requerimientos del software y el diseño de algunos algoritmos numéricos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0ee40347f0418e86bd4566f33c9343eedfbddd424c9054a73adb1818c8b82010'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Muy recomendado. Se aprende bastante y nunca te vas a aburrir en clases'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e6782c04ac7106f695126f08af1704bb09d8184bbffbc76ad4693b81fc99f8b3'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Si en el aula hay una sola persona que diceque tiene experiencia en programar el asume que todos saben. En sus claseslo unico que hace es pasar las diapositivas de presentaciones y leerlas, y cuando uno pregunta dice que para eso estan las horas de consulta y los tutores y que si hemos ido a estas.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-06-09T00:00:00+00:00'::TIMESTAMPTZ, '815691e9279e9854b5950d03f6f294aff95baada76177f2b29fe55fc71508b6f'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Buen profe'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '02959eb4bcc31541c59aa7f7ec5491a134188b1818c5d1d243ad51b4e70701cb'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Le puse 5 en la facilidad para que vean que es un buen profe, pero para esta materia no tiene que buscar si un profe es "fácil" o no, con este profe es difícil pero eso es excelente para quienes tengan que llevar Análisis y Diseño de Algoritmos en algún semestre. Es un excelente profe. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2016-05-17T00:00:00+00:00'::TIMESTAMPTZ, '7bd16cae51d5ba5f34ad5aecac13315d612fdb97d9ceeb9e1ea9ef133173c5ad'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'No lo recomiendo, si ocupas llevar algoritmos o curso similar mejor no meter porque no cubre temas, odioso, repugante, falta el respeto, lo recomiendan porque es flexible con ciertas tareas! Llevelo con el pero ni pregunte en lab lo que se gana es una repugnancia Examenes depende del estado de humor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2016-05-16T00:00:00+00:00'::TIMESTAMPTZ, '1f835354b872863fe7875bd40c6cf156c18dd724836f7a7bd25961df46024f3a'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Se para, no explica el día de lab, repugnante y sin pensar en las groserías que dice, si este curso no te sirve en carrera lleve lo pero si no no porque se salta temas, cae bien porque uno hace lo que quiere con la entrega de todo, no lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'e1f687746493241b593afd059d21a446d65cc5ab99c7815aa6429df0e63b25fb'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Excelente, lo recomiendo mucho. Es una persona muy amable y explica muy bien. Además ayuda mucho y es muy comprensivo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-27T00:00:00+00:00'::TIMESTAMPTZ, '7ca408c7a739c7f3659845e0820ddccfb2d3a056414f320b28f4726d9f64c905'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Demasiado buen profe para elementos! Todo lo explica a la perfeccion y aunque deja bastante brete y no tan facil, vale la pena por sus explicaciones y porque se aprende bien. Es muy buena gente!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd8fc9335ecd86809ec2fa92f18fb3d0b32d07753a7f75dbc9585477696974906'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Recomendado! Explica muy bien y califica normal. Pero sí hay que ponerle al curso por que demanda su tiempillo!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'c2b9906d238514eb18fdd3806bf70a99c76f545a1f75e63f2d1ab33e0dd093d1'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Exelente profesor, explica muy bien y hace los quizes acorde a lo visto en clase, recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'a12aa2132e7cb9a63003d35be89f5ce53fb14780cf038e2e96a80f47e334ee4a'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Excelente profesor, de verdad explica muy bien los temas, hay que estar muy atento en su clase porque le gusta estar preguntando, y si no sabes la respuesta puede que te agarre entre ojos, pero si pones atención la verdad es muy fácil responder. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, '86b0c5e1866e4325e50eba3befb4598ec5a00081449f14a1cdd311780ab194df'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'muy recomendado, es buen profesor, no deja proyectos, pero sí hay que hacer quizzes una vez a la semana y ha mano, sí a uno no le dió tiempo de hacer un lab o una tarea, sí tu hablas con él, siempre te dará más tiempo, explica muy bien, y atiende todas las dudas.. Muy buen profesor, se aprende..'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-16T00:00:00+00:00'::TIMESTAMPTZ, '78c459bb1cfdeccfaa31eaf08039b0e9a0156f21d3aa7109c08a3925e5d0967f'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Si enseña la materia, pero no ve todos los temas del curso, explica solo el dia de teoria y si hay dudas se enoja, si te pregunta y no contestas se enoja y muchas veces pone un ambiente de incomodidad del aula.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '20'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-10T00:00:00+00:00'::TIMESTAMPTZ, '34f253c7ee576ad8e947022c99d7a636c13e2e0ee88725d670712116ec8e9c9e'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Hay que ponerle, explica muy bien, quices relativamente fáciles. Muy flexible para negociar fechas de entrega y califica normal...'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '567047f45d237a4a7d0017f1046665bb6c199fcf95b818b8102b98c5b1877233'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, '¡Muy buen profesor! Siempre se preocupa por los estudiantes, a quienes tratan de preguntarles si entendieron o no para luego repetir lo que explicó el tema que se vio. Muy paciente y en clases se aprende mucho a comparación de las otras. Definitivamente, se lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2015-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'be4b8af7e20170c2b86e8551cd6d38d2bd17a99438958e3125a5c8994982f89d'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es buen profe, explica la materia con claridad. Pregunta mucho en clases y si uno no le responde o le responde mal se enoja. Hay que practicar bastante. Comparado con otros profes es fácil y abarca menos temas que otros profes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '9edfb580490024708baafb5ab35f6b7a3616e86db60acfe1573035256188060c'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'f2868765579f7491a6cd29613e899ef21499d33dd17a542f3a90445d96fbd505'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Buen profe, explica con claridad y se preocupa por el entendimiento de la clase.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'ea160efd958105019fff8d02fb9d68144100e0d86ea5ac0780e0e59bd801a79f'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Se preocupa para que los estudiantes entiendan la materia y atiende muy bien las dudas. Los trabajos no son ni tan faciles pero tampoco tan dificles, solo hay que tomar su tiempo. Recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'cbfdfba4087aae900a92083bd8c34749151798d7100c46f9a9496dd73e52b823'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Recomendado, explica con paciencia, se interesa por los estudiantes, es flexible y buena gente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'b718206be24abcda3d111f459873fc4d1b1d12092c59e6d5b385ef2852220c20'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Buen profe, recomendado, explica bien, hay que practicar y hacer los labs para pasar los quices y exámenes. Progras pesadas pero no imposibles y tan voladas+'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '0a0297548be6b2a2496cc2ace11f8dc21118937c6ed03350e1debc4988e0de8a'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '0f902a3f540177cd5f4185bf0782fd3d0c9c07bc0102dda8cb149a7900195cd6'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Excelente, se preocupa de que los estudiantes esten poniendo antención a la teoría. Y con ir y hacer los laboratorios entiendes los examenes y quices!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, '97d23a8d3e7df2143950d3a525232bea44f5193ece22a67a332f5c883c786253'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'b09544e24f7c577120d2c5db2f373011ed41062473adafe68818ad2f16dc7c72'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'La clase es digamos que dinámica y hace muchas preguntas en ella.Los exámenes son muy parecidos a los laboratorios y no son complicados, pero si deja mucha tarea y siempre hay un quiz escrito por semana.Es exigente con la asistencia y para calificar, no regala nada, es justo en otras palabras.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '68edbea8c45c234bc3619a49edeacdffcbd7754732a869e0120efe6f9038d890'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Muy recomendado, explica claro y su clase es entretenida. Quices y tareas regulares. Califica justo y se preocupa por el estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-08T00:00:00+00:00'::TIMESTAMPTZ, '09325c77c9f56ff04d9be9afe14e8e588dedc436339a6dbea674ee9dee8d9ad3'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'ddaba42d23048485904ada4f1670602cf7e56cf84482f1313d7f495596076d08'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '9f0ceac9b023d9f2b943ce1d10522f205479511a0868f965712c2ca2e47e7738'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '5563fae28e2636e6a64ae3864f704ba3e7cc0470d2cab6d79a5e8cc9935c1435'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Excelente profesor. Los trabajos no son tan faciles como para no poder, pero tampoco tan dificiles como para que sean imposibles. Muy recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'ed96ae7c07ba6dba22d2542195114d13f19b6e0cef0d7920591a98c27e8d7874'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (278::BIGINT, 'Es un buen profe y explica muy bien, los exámenes si son difíciles si uno no hace los laboratorios y no práctica, cualquier duda que uno tenga el con gusto se la aclara y hasta le ayuda a uno.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '0f46123e54b48d50e1ebdcc68d7c88d48cff01605f2d70852a240239a5a9a98f'::TEXT, ARRAY[1020]::BIGINT[]),
    (278::BIGINT, 'Los laboratorios son presenciales lo cuál ayuda montones, los exámenes son un poco rudos pero los quices los hace con base en los Labs y valen 30%, las clases son muy entretenidas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '43dd131ffd89b46f6c06bcf51669f3bfb5c7aef5a75de6b5d2546ce6dde4fc32'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es muy buen profe, pero los examenes si son durillos, deja bastantes tareas que ayudan en la nota final'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '679b741f5711d355c490f4b5becda68ef821930b79c10e2037e4fceb0837ebef'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Bueno profe, hay que ponerle porque los examenes son rudillos, es buena persona, revisa normal, se aprende bastante'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'e2b74b5721bbfa6cc92a471325c1f9c9f283df1e55ad2f8c7c2f0004ae14f801'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Excelente! Hay que ponerle, pero se aprende.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a5e0c17ec3a3a5ff3e0d2be4b8178f51b9c7f662ea4dabb6f1ceb3c534cb959a'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '0f14c685bf33874056cf008a64b06af9ff83f2e32586f9bbf1ae0c97050f73cd'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'profe muy interesado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'aee5c94dc27284d689a29aae310b5f57a019f65c77ba0916c8dff47576c02e5a'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Es un buen profe, enseña muy bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '41b22a277cad5ca3f09ab72ed39057d4bd34249a7d3afe5a6c606906e5027b8c'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Si quiere aprender, dele viaje'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'd68290629fa3723d4a129f3ce587d7fc3e7bd1fa961999f324ece921a98f8d70'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'bdc587927fc92689044d7c25d0728d8a432dcb8256a2a52b5343aebcd3c92ae5'::TEXT, ARRAY[1249]::BIGINT[]),
    (278::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'fdee4cf86f4b0179eda13ffa29e45a52f28c986522d85480daa4086996e39453'::TEXT, ARRAY[1020, 1022]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
